parameters.jsCode:
const msg = $input.first().json;
const attachments = msg.attachments || [];
const pdf = attachments.find(a => a.fileType === 'pdf' || a.fileName?.endsWith('.pdf'));
const docx = attachments.find(a => a.fileName?.endsWith('.docx'));
return [{ json: { hasAttachment: attachments.length > 0, pdf, docx, subject: msg.subject, from: msg.from } }];

